// Collect the domains of column "domain" into one list (one Actor run for the whole sheet, up to 10,000 domains).
const domains = $input.all()
  .map((item) => String(item.json.domain ?? '').trim())
  .filter(Boolean);
if (domains.length === 0) throw new Error('No domain found: add a column named "domain" to the Prospects tab.');
return [{ json: { domains } }];

// One row per domain with a keep / check / skip verdict from the thresholds in Settings.
const { minRank, maxSpamScore } = $('Settings').first().json;
return $input.all()
  .map((i) => i.json)
  .filter((d) => d.domain)
  .map((d) => {
    let verdict = 'no data';
    if (d.found !== false && d.domainRank != null) {
      if (d.spamScore != null && d.spamScore > maxSpamScore) verdict = 'skip (spam)';
      else if (d.domainRank >= minRank) verdict = 'keep';
      else verdict = 'check (low rank)';
    }
    return {
      json: {
        domain: d.domain,
        domainRank: d.domainRank ?? null,
        spamScore: d.spamScore ?? null,
        verdict,
        checkedAt: d.observedAt,
      },
    };
  });
